-- 02 OPCIONAL — Importa os mesmos 41 registros FICTÍCIOS do protótipo original.
-- Coordenadas e dados da demonstração NÃO representam instalações, contratos ou obras reais.
-- Importe apenas em banco preparado para demonstração (após 01_estrutura_e_suporte.sql).
SET NAMES utf8mb4;
UPDATE sequences SET last_number=GREATEST(last_number, 8) WHERE module='obras';
UPDATE sequences SET last_number=GREATEST(last_number, 86) WHERE module='ordens';
UPDATE sequences SET last_number=GREATEST(last_number, 18) WHERE module='fiscalizacao';
UPDATE sequences SET last_number=GREATEST(last_number, 41) WHERE module='projetos';
UPDATE sequences SET last_number=GREATEST(last_number, 8) WHERE module='orcamentos';
UPDATE sequences SET last_number=GREATEST(last_number, 6) WHERE module='materiais';
UPDATE sequences SET last_number=GREATEST(last_number, 4) WHERE module='patrimonio';
UPDATE sequences SET last_number=GREATEST(last_number, 184) WHERE module='protocolos';
